<?php $__env->startSection('title','طلب دعم'); ?>
<?php $__env->startSection('content'); ?>
<header class="page-header"><div><div class="eyebrow">طلب #<?php echo e(Str::limit($ticket->public_id,8,'')); ?></div><h1><?php echo e($ticket->subject); ?></h1><p><?php echo e($ticket->user->name); ?> · <?php echo e($ticket->user->email); ?> · <?php echo e($ticket->category); ?></p></div><a class="button button-quiet" href="<?php echo e(route('admin.support-tickets.index')); ?>">العودة للطلبات</a></header>
<section class="grid content-columns"><main class="card"><div class="section-heading"><h2>المحادثة</h2><span class="badge draft"><?php echo e($ticket->status); ?></span></div><div class="support-timeline"><?php $__currentLoopData = $ticket->messages; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $message): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><article><span class="timeline-icon"><?php echo e($message->user->isAdmin()?'A':'ط'); ?></span><div><strong><?php echo e($message->user->name); ?></strong><p><?php echo e($message->body); ?></p><?php if($message->attachment_path): ?><a class="button button-quiet" href="<?php echo e(route('admin.support-tickets.attachment',$message)); ?>" target="_blank" rel="noopener">فتح المرفق · <?php echo e($message->attachment_name); ?></a><?php endif; ?><small><?php echo e($message->created_at->format('Y/m/d H:i')); ?></small></div></article><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div></main>
<aside class="stack"><section class="card"><div class="section-heading"><h2>إرسال رد</h2></div><?php if($ticket->status!=='closed'): ?><form class="stack" method="post" action="<?php echo e(route('admin.support-tickets.reply',$ticket)); ?>"><?php echo csrf_field(); ?><label>الرد<textarea name="message" required minlength="5" maxlength="5000"></textarea></label><label>الحالة بعد الرد<select name="status"><option value="waiting_student">بانتظار الطالب</option><option value="in_progress">قيد المعالجة</option><option value="resolved">تم الحل</option></select></label><button class="button button-primary">إرسال الرد</button></form><?php else: ?><p>هذا الطلب مغلق.</p><?php endif; ?></section><section class="card"><form class="stack" method="post" action="<?php echo e(route('admin.support-tickets.update',$ticket)); ?>"><?php echo csrf_field(); ?> <?php echo method_field('put'); ?><label>تحديث الحالة<select name="status"><?php $__currentLoopData = ['open'=>'جديد','in_progress'=>'قيد المعالجة','waiting_student'=>'بانتظار الطالب','resolved'=>'تم الحل','closed'=>'مغلق']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $value=>$label): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($value); ?>" <?php if($ticket->status===$value): echo 'selected'; endif; ?>><?php echo e($label); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></label><button class="button button-secondary">حفظ الحالة</button></form></section></aside></section>
<?php $__env->stopSection(); ?>

